    /// </param>
    /// <param name="y">
    /// the y coordinate of the window, or <c>SDL_WINDOWPOS_CENTERED</c> or <c>SDL_WINDOWPOS_UNDEFINED</c>.
    /// </param>
    /// <returns>true on success or false on failure; call SDL_GetError() for more information.</returns>
