    /// See also: <c>SDL_SetWindowSize</c>, <c>SDL_SetWindowPosition</c>, <c>SDL_SetWindowFullscreen</c>,
    /// <c>SDL_MinimizeWindow</c>, <c>SDL_MaximizeWindow</c>, <c>SDL_RestoreWindow</c>,
    /// <c>SDL_HINT_VIDEO_SYNC_WINDOW_OPERATIONS</c>.
