    /// a rectangle area in window-relative coordinates. If NULL the barrier for the specified window will be destroyed.
    /// </param>
    /// <returns>true on success or false on failure; call SDL_GetError() for more information.</returns>
    public byte SetMouseRect(Rect* rect) => Sdl.SetWindowMouseRect(this, rect);

    /// <summary>Confines the cursor to the specified area of a window.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_SetWindowMouseRect</c>.</para>
    /// <para>
    /// Note that this does NOT grab the cursor, it only defines the area a cursor is restricted to when the window has
    /// mouse focus.
    /// </para>
    /// <para>Thread safety: This function should only be called on the main thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>
    /// See also: <c>SDL_GetWindowMouseRect</c>, <c>SDL_GetWindowMouseGrab</c>, <c>SDL_SetWindowMouseGrab</c>.
    /// </para>
    /// </remarks>
    /// <param name="rect">
    /// a rectangle area in window-relative coordinates. If NULL the barrier for the specified window will be destroyed.
    /// </param>
    /// <returns>true on success or false on failure; call SDL_GetError() for more information.</returns>
    public byte SetMouseRect(in Rect rect) => Sdl.SetWindowMouseRect(this, in rect);

    /// <summary>Get the mouse confinement rectangle of a window.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_GetWindowMouseRect</c>.</para>
    /// <para>Thread safety: This function should only be called on the main thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>
    /// See also: <c>SDL_SetWindowMouseRect</c>, <c>SDL_GetWindowMouseGrab</c>, <c>SDL_SetWindowMouseGrab</c>.
    /// </para>
    /// </remarks>
    /// <returns>a pointer to the mouse confinement rectangle of a window, or NULL if there isn't one.</returns>
    public Rect* GetMouseRect() => Sdl.GetWindowMouseRect(this);

    /// <summary>Set the opacity for a window.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_SetWindowOpacity</c>.</para>
    /// <para>
    /// The parameter <c>opacity</c> will be clamped internally between 0.0f (transparent) and 1.0f (opaque).
    /// </para>
    /// <para>This function also returns false if setting the opacity isn't supported.</para>
    /// <para>Thread safety: This function should only be called on the main thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>See also: <c>SDL_GetWindowOpacity</c>.</para>
    /// </remarks>
    /// <param name="opacity">the opacity value (0.0f - transparent, 1.0f - opaque).</param>
    /// <returns>true on success or false on failure; call SDL_GetError() for more information.</returns>
    public byte SetOpacity(float opacity) => Sdl.SetWindowOpacity(this, opacity);

    /// <summary>Get the opacity of a window.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_GetWindowOpacity</c>.</para>
    /// <para>If transparency isn't supported on this platform, opacity will be returned as 1.0f without error.</para>
    /// <para>Thread safety: This function should only be called on the main thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>See also: <c>SDL_SetWindowOpacity</c>.</para>
    /// </remarks>
    /// <returns>
    /// the opacity, (0.0f - transparent, 1.0f - opaque), or -1.0f on failure; call SDL_GetError() for more information.
    /// </returns>
    public float GetOpacity() => Sdl.GetWindowOpacity(this);

    /// <summary>Set the window as a child of a parent window.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_SetWindowParent</c>.</para>
    /// <para>
    /// If the window is already the child of an existing window, it will be reparented to the new owner. Setting the
    /// parent window to NULL unparents the window and removes child window status.
    /// </para>
    /// <para>
    /// If a parent window is hidden or destroyed, the operation will be recursively applied to child windows. Child
    /// windows hidden with the parent that did not have their hidden status explicitly set will be restored when the
    /// parent is shown.
    /// </para>
    /// <para>
    /// Attempting to set the parent of a window that is currently in the modal state will fail. Use
    /// SDL_SetWindowModal() to cancel the modal status before attempting to change the parent.
    /// </para>
    /// <para>Popup windows cannot change parents and attempts to do so will fail.</para>
    /// <para>
    /// Setting a parent window that is currently the sibling or descendent of the child window results in undefined
    /// behavior.
    /// </para>
    /// <para>Thread safety: This function should only be called on the main thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>See also: <c>SDL_SetWindowModal</c>.</para>
    /// </remarks>
    /// <param name="parent">the new parent window for the child window.</param>
    /// <returns>true on success or false on failure; call SDL_GetError() for more information.</returns>
    public byte SetParent(Window parent) => Sdl.SetWindowParent(this, parent);

    /// <summary>Toggle the state of the window as modal.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_SetWindowModal</c>.</para>
    /// <para>
    /// To enable modal status on a window, the window must currently be the child window of a parent, or toggling modal
    /// status on will fail.
    /// </para>
    /// <para>Thread safety: This function should only be called on the main thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>See also: <c>SDL_SetWindowParent</c>, <c>SDL_WINDOW_MODAL</c>.</para>
    /// </remarks>
    /// <param name="modal">true to toggle modal status on, false to toggle it off.</param>
    /// <returns>true on success or false on failure; call SDL_GetError() for more information.</returns>
    public byte SetModal(byte modal) => Sdl.SetWindowModal(this, modal);

    /// <summary>Set whether the window may have input focus.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_SetWindowFocusable</c>.</para>
    /// <para>Thread safety: This function should only be called on the main thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// </remarks>
    /// <param name="focusable">true to allow input focus, false to not allow input focus.</param>
    /// <returns>true on success or false on failure; call SDL_GetError() for more information.</returns>
    public byte SetFocusable(byte focusable) => Sdl.SetWindowFocusable(this, focusable);

    /// <summary>Display the system-level window menu.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_ShowWindowSystemMenu</c>.</para>
    /// <para>
    /// This default window menu is provided by the system and on some platforms provides functionality for setting or
    /// changing privileged state on the window, such as moving it between workspaces or displays, or toggling the
    /// always-on-top property.
    /// </para>
    /// <para>On platforms or desktops where this is unsupported, this function does nothing.</para>
    /// <para>Thread safety: This function should only be called on the main thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// </remarks>
    /// <param name="x">the x coordinate of the menu, relative to the origin (top-left) of the client area.</param>
    /// <param name="y">the y coordinate of the menu, relative to the origin (top-left) of the client area.</param>
    /// <returns>true on success or false on failure; call SDL_GetError() for more information.</returns>
    public byte ShowSystemMenu(int x, int y) => Sdl.ShowWindowSystemMenu(this, x, y);

    /// <summary>Provide a callback that decides if a window region has special properties.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_SetWindowHitTest</c>.</para>
    /// <para>
    /// Normally windows are dragged and resized by decorations provided by the system window manager (a title bar,
    /// borders, etc), but for some apps, it makes sense to drag them from somewhere else inside the window itself; for
    /// example, one might have a borderless window that wants to be draggable from any part, or simulate its own title
    /// bar, etc.
    /// </para>
    /// <para>
    /// This function lets the app provide a callback that designates pieces of a given window as special. This callback
    /// is run during event processing if we need to tell the OS to treat a region of the window specially; the use of
    /// this callback is known as "hit testing."
    /// </para>
    /// <para>
    /// Mouse input may not be delivered to your application if it is within a special area; the OS will often apply
    /// that input to moving the window or resizing the window and not deliver it to the application.
    /// </para>
    /// <para>Specifying NULL for a callback disables hit-testing. Hit-testing is disabled by default.</para>
    /// <para>
    /// Platforms that don't support this functionality will return false unconditionally, even if you're attempting to
    /// disable hit-testing.
    /// </para>
    /// <para>
    /// Your callback may fire at any time, and its firing does not indicate any specific behavior (for example, on
    /// Windows, this certainly might fire when the OS is deciding whether to drag your window, but it fires for lots of
    /// other reasons, too, some unrelated to anything you probably care about _and when the mouse isn't actually at the
    /// location it is testing_). Since this can fire at any time, you should try to keep your callback efficient,
    /// devoid of allocations, etc.
    /// </para>
    /// <para>Thread safety: This function should only be called on the main thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// </remarks>
    /// <param name="callback">the function to call when doing a hit-test.</param>
    /// <param name="callbackData">an app-defined void pointer passed to <b>callback</b>.</param>
    /// <returns>true on success or false on failure; call SDL_GetError() for more information.</returns>
    public byte SetHitTest(delegate* unmanaged[Cdecl]<Window, Point*, void*, HitTestResult> callback, void* callbackData) => Sdl.SetWindowHitTest(this, callback, callbackData);

    /// <summary>Set the shape of a transparent window.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_SetWindowShape</c>.</para>
    /// <para>
    /// This sets the alpha channel of a transparent window and any fully transparent areas are also transparent to
    /// mouse clicks. If you are using something besides the SDL render API, then you are responsible for drawing the
    /// alpha channel of the window to match the shape alpha channel to get consistent cross-platform results.
    /// </para>
    /// <para>
    /// The shape is copied inside this function, so you can free it afterwards. If your shape surface changes, you
    /// should call SDL_SetWindowShape() again to update the window. This is an expensive operation, so should be done
    /// sparingly.
    /// </para>
    /// <para>The window must have been created with the SDL_WINDOW_TRANSPARENT flag.</para>
    /// <para>Thread safety: This function should only be called on the main thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// </remarks>
    /// <param name="shape">
    /// the surface representing the shape of the window, or NULL to remove any current shape.
    /// </param>
    /// <returns>true on success or false on failure; call SDL_GetError() for more information.</returns>
    public byte SetShape(Surface* shape) => Sdl.SetWindowShape(this, shape);

    /// <summary>Request a window to demand attention from the user.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_FlashWindow</c>.</para>
    /// <para>Thread safety: This function should only be called on the main thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// </remarks>
    /// <param name="operation">the operation to perform.</param>
    /// <returns>true on success or false on failure; call SDL_GetError() for more information.</returns>
    public byte Flash(FlashOperation operation) => Sdl.FlashWindow(this, operation);

    /// <summary>Sets the state of the progress bar for the given window’s taskbar icon.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_SetWindowProgressState</c>.</para>
    /// <para>Thread safety: This function should only be called on the main thread.</para>
    /// <para>This function is available since SDL 3.4.0.</para>
    /// </remarks>
    /// <param name="state">
    /// the progress state. <c>SDL_PROGRESS_STATE_NONE</c> stops displaying the progress bar.
    /// </param>
    /// <returns>true on success or false on failure; call SDL_GetError() for more information.</returns>
    public byte SetProgressState(ProgressState state) => Sdl.SetWindowProgressState(this, state);

    /// <summary>Get the state of the progress bar for the given window’s taskbar icon.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_GetWindowProgressState</c>.</para>
    /// <para>Thread safety: This function should only be called on the main thread.</para>
    /// <para>This function is available since SDL 3.4.0.</para>
    /// </remarks>
    /// <returns>
    /// the progress state, or <c>SDL_PROGRESS_STATE_INVALID</c> on failure; call SDL_GetError() for more information.
    /// </returns>
    public ProgressState GetProgressState() => Sdl.GetWindowProgressState(this);

    /// <summary>Sets the value of the progress bar for the given window’s taskbar icon.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_SetWindowProgressValue</c>.</para>
    /// <para>Thread safety: This function should only be called on the main thread.</para>
    /// <para>This function is available since SDL 3.4.0.</para>
    /// </remarks>
    /// <param name="value">
    /// the progress value in the range of [0.0f - 1.0f]. If the value is outside the valid range, it gets clamped.
    /// </param>
    /// <returns>true on success or false on failure; call SDL_GetError() for more information.</returns>
    public byte SetProgressValue(float value) => Sdl.SetWindowProgressValue(this, value);

    /// <summary>Get the value of the progress bar for the given window’s taskbar icon.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_GetWindowProgressValue</c>.</para>
    /// <para>Thread safety: This function should only be called on the main thread.</para>
    /// <para>This function is available since SDL 3.4.0.</para>
    /// </remarks>
    /// <returns>
    /// the progress value in the range of [0.0f - 1.0f], or -1.0f on failure; call SDL_GetError() for more information.
    /// </returns>
    public float GetProgressValue() => Sdl.GetWindowProgressValue(this);

    /// <summary>Destroy a window.</summary>
    /// <remarks>
    /// <para>Binds <c>SDL_DestroyWindow</c>.</para>
    /// <para>Any child windows owned by the window will be recursively destroyed as well.</para>
    /// <para>
    /// Note that on some platforms, the visible window may not actually be removed from the screen until the SDL event
    /// loop is pumped again, even though the SDL_Window is no longer valid after this call.
    /// </para>
    /// <para>Thread safety: This function should only be called on the main thread.</para>
    /// <para>This function is available since SDL 3.2.0.</para>
    /// <para>
    /// See also: <c>SDL_CreatePopupWindow</c>, <c>SDL_CreateWindow</c>, <c>SDL_CreateWindowWithProperties</c>.
    /// </para>
    /// </remarks>
    public void Destroy() => Sdl.DestroyWindow(this);
}
